"""Writes tools/stats/cases_t6.txt: classification learners (fitcknn, fitcnb, fitcdiscr) and their methods."""
import os
here = os.path.dirname(os.path.abspath(__file__))
PRE = ("Xc=[x(1:60)' y(1:60)']; Yc=[ones(20,1);2*ones(20,1);3*ones(20,1)]; Xc(Yc==2,:)=Xc(Yc==2,:)+1.5; Xc(Yc==3,:)=Xc(Yc==3,:)-1.5; "
       "ub=[1:20 21:35 41:50]'; Xu=Xc(ub,:); Yu=Yc(ub); Xn=[0.2 0.1;1.4 1.5;-1.2 -1.3;0.9 0.2;-0.3 -0.6;1.1 1.9]; Ys=repmat({'a'},20,1); Ys=[Ys;repmat({'b'},20,1);repmat({'c'},20,1)]; ")
L = ["# generated by make_t6_cases.py"]
def add(cs, fmt):
    for c in cs:
        L.append(fmt.replace("{c}", c))
KPROPS = "{m.NumNeighbors, m.Distance, m.DistParameter, m.IncludeTies, m.DistanceWeight, m.BreakTies, m.NSMethod, m.Mu, m.Sigma, m.Y, m.X, m.RowsUsed, m.W, m.NumObservations, m.PredictorNames, m.CategoricalPredictors, m.ResponseName, m.ExpandedPredictorNames, m.ClassNames, m.Prior, m.Cost, m.ScoreTransform}"
BPROPS = "{m.Y, m.X, m.RowsUsed, m.W, m.NumObservations, m.PredictorNames, m.CategoricalPredictors, m.ResponseName, m.ExpandedPredictorNames, m.ClassNames, m.Prior, m.Cost, m.ScoreTransform}"
NBPROPS = "{m.DistributionNames, m.DistributionParameters, m.Mu, m.Sigma, m.CategoricalLevels, m.Kernel, m.Support, m.Width}"
DPROPS = "{m.DiscrimType, m.Gamma, m.Delta, m.Mu, m.Sigma, m.BetweenSigma, m.LogDetSigma, m.MinGamma, m.DeltaPredictor, m.XCentered}"
knn_fits = ["fitcknn(Xc,Yc)", "fitcknn(Xc,Yc,'NumNeighbors',3)", "fitcknn(Xc,Yc,'NumNeighbors',5,'Distance','cityblock')", "fitcknn(Xc,Yc,'Distance','chebychev')", "fitcknn(Xc,Yc,'NumNeighbors',3,'Distance','minkowski','Exponent',3)", "fitcknn(Xc,Yc,'Distance','cosine')",
            "fitcknn(Xc,Yc,'Distance','correlation')", "fitcknn(Xc,Yc,'Distance','spearman')", "fitcknn(Xc,Yc,'Distance','mahalanobis')", "fitcknn(Xc,Yc,'Distance','seuclidean')", "fitcknn(Xc,Yc,'Distance','hamming')", "fitcknn(Xc,Yc,'Standardize',true)",
            "fitcknn(Xc,Yc,'NumNeighbors',4,'DistanceWeight','inverse')", "fitcknn(Xc,Yc,'NumNeighbors',4,'DistanceWeight','squaredinverse')", "fitcknn(Xc,Yc,'Prior','uniform')", "fitcknn(Xu,Yu)", "fitcknn(Xu,Yu,'Prior','uniform')", "fitcknn(Xu,Yu,'Prior',[0.5 0.3 0.2])",
            "fitcknn(Xc,Ys)", "fitcknn(Xc,Yc,'ClassNames',[3 1 2])", "fitcknn(Xc,Yc,'Cost',[0 1 2;1 0 1;3 1 0])", "fitcknn(Xc,Yc,'NumNeighbors',4,'IncludeTies',true)", "fitcknn(Xc,Yc,'NumNeighbors',3,'BreakTies','nearest')", "fitcknn(Xc,Yc,'PredictorNames',{'a','b'},'ResponseName','cls')",
            "fitcknn(Xc,Yc,'Weights',(1:60)')", "fitcknn(Xc,Yc,'NSMethod','exhaustive')", "fitcknn(Xc,Yc,'Distance',@(a,b) sum(abs(a-b),2))"]
add(knn_fits, "m = {c}; r = " + KPROPS + ";")
errs = ["fitcknn(Xc)", "fitcknn(Xc,Yc(1:5))", "fitcknn(Xc,Yc,'NumNeighbors',0)", "fitcknn(Xc,Yc,'Distance','foo')", "fitcknn(Xc,Yc,'Foo',1)", "fitcknn(Xc,Yc,'Prior',[1 2])", "fitcknn(Xc,Yc,'Cost',eye(2))", "fitcknn(Xc,Yc,'NumNeighbors',2.5)", "fitcknn(Xc,Yc,'BreakTies','foo')", "fitcknn(Xc,Yc,'DistanceWeight','foo')", "fitcknn(Xc(1:3,:),[1;2;3])", "fitcknn([Xc;NaN 1],[Yc;1])", "fitcknn(Xc,[Yc(1:59);NaN])", "fitcknn(Xc,Yc,'ClassNames',[1 2])"]
add(errs, "m = {c}; r = 1;")
kn = "fitcknn(Xc,Yc,'NumNeighbors',3)"
meth = ["[l,s,c] = predict(m,Xn); r = {l,s,c};", "[l,s,c] = resubPredict(m); r = {l,s(1:10,:),c(1:10,:)};", "r = loss(m,Xn,[1;2;3;1;3;2]);", "r = loss(m,Xn,[1;2;3;1;3;2],'LossFun','binodeviance');", "r = loss(m,Xn,[1;2;3;1;3;2],'LossFun','exponential');", "r = loss(m,Xn,[1;2;3;1;3;2],'LossFun','hinge');", "r = loss(m,Xn,[1;2;3;1;3;2],'LossFun','logit');",
        "r = loss(m,Xn,[1;2;3;1;3;2],'LossFun','mincost');", "r = loss(m,Xn,[1;2;3;1;3;2],'LossFun','quadratic');", "r = loss(m,Xn,[1;2;3;1;3;2],'Weights',[1 2 3 4 5 6]');", "r = resubLoss(m);", "r = resubLoss(m,'LossFun','mincost');", "r = margin(m,Xn,[1;2;3;1;3;2]);", "r = edge(m,Xn,[1;2;3;1;3;2]);", "r = resubMargin(m);", "r = resubEdge(m);",
        "r = predict(m,Xn(:,1));", "r = predict(m);", "r = loss(m,Xn,[1;2;3]);", "r = loss(m,Xn,[1;2;3;1;3;5]);", "r = predict(m,[Xn;NaN 1]);", "r = predict(m,single(Xn));", "r = loss(m,Xn,[1;2;3;1;3;2],'LossFun','foo');"]
add(meth, "m = " + kn + "; {c}")
for fit in ["fitcknn(Xu,Yu,'NumNeighbors',5)", "fitcknn(Xu,Yu,'NumNeighbors',5,'Prior','uniform')", "fitcknn(Xc,Ys,'NumNeighbors',3)", "fitcknn(Xc,Yc,'NumNeighbors',4,'DistanceWeight','inverse')", "fitcknn(Xc,Yc,'NumNeighbors',4,'IncludeTies',true)", "fitcknn(Xc,Yc,'NumNeighbors',4,'BreakTies','nearest')", "fitcknn(Xc,Yc,'Distance','cityblock','Standardize',true)", "fitcknn(Xc,Yc,'Cost',[0 1 2;1 0 1;3 1 0],'NumNeighbors',5)", "fitcknn(Xc,Yc,'Distance','mahalanobis','NumNeighbors',3)", "fitcknn(Xc,Yc,'Weights',(1:60)','NumNeighbors',3)"]:
    L.append("m = " + fit + "; [l,s,c] = predict(m,Xn); r = {l,s,c,loss(m,Xn,[1;2;3;1;3;2]),resubLoss(m),margin(m,Xn,[1;2;3;1;3;2])};")
nbf = ["fitcnb(Xc,Yc)", "fitcnb(Xu,Yu)", "fitcnb(Xu,Yu,'Prior','uniform')", "fitcnb(Xc,Ys)", "fitcnb(Xc,Yc,'Prior',[0.5 0.3 0.2])", "fitcnb(Xc,Yc,'DistributionNames','normal')", "fitcnb(Xc,Yc,'DistributionNames',{'normal','normal'})", "fitcnb(Xc,Yc,'Weights',(1:60)')", "fitcnb(Xc,Yc,'Cost',[0 1 2;1 0 1;3 1 0])", "fitcnb(Xc,Yc,'ClassNames',[3 2 1])", "fitcnb(Xc,Yc,'PredictorNames',{'a','b'},'ResponseName','cls')"]
add(nbf, "m = {c}; r = " + BPROPS + ";")
add(nbf, "m = {c}; r = " + NBPROPS + ";")
add(["fitcnb(Xc)", "fitcnb(Xc,Yc(1:5))", "fitcnb(Xc,Yc,'DistributionNames','foo')", "fitcnb(Xc,Yc,'Foo',1)", "fitcnb(Xc,Yc,'Prior',[1 2])", "fitcnb([Xc(1:20,:);Xc(21:60,:)*0+1],Yc)", "fitcnb(Xc,Yc,'DistributionNames',{'normal'})"], "m = {c}; r = 1;")
nbfits = ["fitcnb(Xc,Yc)", "fitcnb(Xu,Yu)", "fitcnb(Xu,Yu,'Prior','uniform')", "fitcnb(Xc,Ys)", "fitcnb(Xc,Yc,'Weights',(1:60)')", "fitcnb(Xc,Yc,'Cost',[0 1 2;1 0 1;3 1 0])"]
for fit in nbfits:
    L.append("m = " + fit + "; [l,s,c] = predict(m,Xn); r = {l,s,c,loss(m,Xn,[1;2;3;1;3;2]),resubLoss(m),margin(m,Xn,[1;2;3;1;3;2]),edge(m,Xn,[1;2;3;1;3;2]),resubEdge(m)};")
add(["loss(m,Xn,[1;2;3;1;3;2],'LossFun','binodeviance')", "loss(m,Xn,[1;2;3;1;3;2],'LossFun','exponential')", "loss(m,Xn,[1;2;3;1;3;2],'LossFun','hinge')", "loss(m,Xn,[1;2;3;1;3;2],'LossFun','logit')", "loss(m,Xn,[1;2;3;1;3;2],'LossFun','mincost')", "loss(m,Xn,[1;2;3;1;3;2],'LossFun','quadratic')", "resubLoss(m,'LossFun','quadratic')", "predict(m,Xn(:,1))", "resubPredict(m)", "resubMargin(m)"], "m = fitcnb(Xc,Yc); r = {c};")
df = ["fitcdiscr(Xc,Yc)", "fitcdiscr(Xc,Yc,'DiscrimType','quadratic')", "fitcdiscr(Xc,Yc,'DiscrimType','diaglinear')", "fitcdiscr(Xc,Yc,'DiscrimType','diagquadratic')", "fitcdiscr(Xu,Yu)", "fitcdiscr(Xu,Yu,'Prior','uniform')", "fitcdiscr(Xc,Ys)", "fitcdiscr(Xc,Yc,'Prior',[0.5 0.3 0.2])", "fitcdiscr(Xc,Yc,'Weights',(1:60)')", "fitcdiscr(Xc,Yc,'Cost',[0 1 2;1 0 1;3 1 0])", "fitcdiscr(Xc,Yc,'DiscrimType','pseudolinear')", "fitcdiscr(Xc,Yc,'DiscrimType','pseudoquadratic')", "fitcdiscr(Xc,Yc,'Gamma',0.3)", "fitcdiscr(Xc,Yc,'Delta',0.05)"]
add(df, "m = {c}; r = " + BPROPS + ";")
add(df, "m = {c}; r = " + DPROPS + ";")
add(["fitcdiscr(Xc)", "fitcdiscr(Xc,Yc(1:5))", "fitcdiscr(Xc,Yc,'DiscrimType','foo')", "fitcdiscr(Xc,Yc,'Foo',1)", "fitcdiscr(Xc,Yc,'Prior',[1 2])", "fitcdiscr([Xc(:,1) Xc(:,1)],Yc)", "fitcdiscr(Xc,Yc,'Gamma',2)", "fitcdiscr(Xc(1:3,:),[1;2;3])", "fitcdiscr(Xc,Yc,'Delta',-1)"], "m = {c}; r = 1;")
for fit in df[:11]:
    L.append("m = " + fit + "; [l,s,c] = predict(m,Xn); r = {l,s,c,loss(m,Xn,[1;2;3;1;3;2]),resubLoss(m),margin(m,Xn,[1;2;3;1;3;2]),edge(m,Xn,[1;2;3;1;3;2]),resubEdge(m)};")
add(["loss(m,Xn,[1;2;3;1;3;2],'LossFun','binodeviance')", "loss(m,Xn,[1;2;3;1;3;2],'LossFun','mincost')", "resubPredict(m)", "predict(m,Xn(:,1))", "m.Coeffs(1,2).Const", "m.Coeffs(1,2).Linear", "m.Coeffs(2,1).Linear", "m.Coeffs(1,2).Name1", "m.Coeffs(1,2).Type", "m.Coeffs(1,1).Const", "size(m.Coeffs)"], "m = fitcdiscr(Xc,Yc); r = {c};")
add(["m.Coeffs(1,2).Quadratic", "m.Coeffs(1,2).Const", "m.Coeffs(1,2).Linear", "m.Coeffs(1,2).Type"], "m = fitcdiscr(Xc,Yc,'DiscrimType','quadratic'); r = {c};")
L = [L[0]] + [PRE + l for l in L[1:]]
with open(os.path.join(here, "cases_t6.txt"), "w", encoding="utf-8", newline="\n") as f:
    f.write("\n".join(L) + "\n")
print(len(L))
